import { createHash, randomUUID } from 'node:crypto';
import { mkdir, readFile, writeFile, rename, rmdir, stat } from 'node:fs/promises';
import path from 'node:path';

export const REASON_CODES = [
  'sent_requested',
  'sent_reminder',
  'sent_suggestion',
  'already_delivered',
  'new_user_waiting_period',
  'quiet_hours',
  'daily_limit_reached',
  'unknown_notification_type',
  'missing_user_details',
];

const HOUR = 3600 * 1000;
const DAY = 24 * HOUR;
// Suggestions the assistant guessed are held back for new users.
const NEW_USER_WAIT_MS = 3 * DAY;
// Suggestions are not sent between 21:00 and 08:00 in the user's local time.
const QUIET_START = 21;
const QUIET_END = 8;
// Delivered ids are remembered this long, to block duplicates.
const ID_MEMORY_MS = 90 * DAY;
const LOCK_STALE_MS = 10_000;
const LOCK_TIMEOUT_MS = 30_000;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error('STATE_DIR is not set');
  return dir;
}

async function withLock(file, fn) {
  const lock = file + '.lock';
  const start = Date.now();
  for (;;) {
    try {
      await mkdir(lock);
      break;
    } catch (e) {
      if (e.code !== 'EEXIST') throw e;
      try {
        const s = await stat(lock);
        if (Date.now() - s.mtimeMs > LOCK_STALE_MS) {
          // Only one process can win this rename, so only one breaks the lock.
          const grave = `${lock}.stale-${randomUUID()}`;
          await rename(lock, grave);
          await rmdir(grave).catch(() => {});
          continue;
        }
      } catch {
        continue; // lock vanished or was taken over; retry
      }
      if (Date.now() - start > LOCK_TIMEOUT_MS) throw new Error('lock timeout');
      await sleep(5 + Math.random() * 20);
    }
  }
  try {
    return await fn();
  } finally {
    await rmdir(lock).catch(() => {});
  }
}

async function readState(file) {
  try {
    const s = JSON.parse(await readFile(file, 'utf8'));
    return {
      delivered: s.delivered && typeof s.delivered === 'object' ? s.delivered : {},
      nudges: s.nudges && typeof s.nudges === 'object' ? s.nudges : {},
    };
  } catch (e) {
    if (e.code === 'ENOENT') return { delivered: {}, nudges: {} };
    throw e;
  }
}

async function writeState(file, state) {
  const tmp = `${file}.${process.pid}.${randomUUID()}.tmp`;
  await writeFile(tmp, JSON.stringify(state));
  await rename(tmp, file);
}

function validTimezone(tz) {
  try {
    new Intl.DateTimeFormat('en-US', { timeZone: tz });
    return typeof tz === 'string' && tz ? tz : 'UTC';
  } catch {
    return 'UTC';
  }
}

function localParts(date, tz) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    hourCycle: 'h23',
  }).formatToParts(date);
  const get = (t) => parts.find((p) => p.type === t).value;
  return { day: `${get('year')}-${get('month')}-${get('day')}`, hour: Number(get('hour')) };
}

function inQuietHours(hour) {
  return QUIET_START > QUIET_END
    ? hour >= QUIET_START || hour < QUIET_END
    : hour >= QUIET_START && hour < QUIET_END;
}

export async function decide({ user, candidate, now, config } = {}) {
  if (!user || typeof user.id !== 'string' || !user.id || !candidate || candidate.id == null) {
    return { send: false, reasonCode: 'missing_user_details' };
  }
  const origin = candidate.origin;
  if (origin !== 'requested' && origin !== 'inferred' && origin !== 'reminder') {
    return { send: false, reasonCode: 'unknown_notification_type' };
  }
  const nowDate = now instanceof Date && !isNaN(now) ? now : new Date();
  const nowMs = nowDate.getTime();
  const candId = String(candidate.id);

  // Account age: the newest known start date. Unknown dates count as "new".
  let accountStart = NaN;
  if (origin === 'inferred') {
    const times = [user.createdAt, user.profileCreatedAt].map((d) => Date.parse(d)).filter((t) => !isNaN(t));
    accountStart = times.length ? Math.max(...times) : NaN;
  }

  const dir = stateDir();
  await mkdir(dir, { recursive: true });
  const file = path.join(dir, `user-${createHash('sha256').update(user.id).digest('hex').slice(0, 32)}.json`);

  return withLock(file, async () => {
    const state = await readState(file);

    for (const [id, t] of Object.entries(state.delivered)) {
      if (nowMs - t > ID_MEMORY_MS) delete state.delivered[id];
    }
    if (state.delivered[candId] !== undefined) {
      return { send: false, reasonCode: 'already_delivered' };
    }

    if (origin === 'requested' || origin === 'reminder') {
      // The user asked for these. They skip quiet hours and the nudge limit.
      state.delivered[candId] = nowMs;
      await writeState(file, state);
      return { send: true, reasonCode: origin === 'requested' ? 'sent_requested' : 'sent_reminder' };
    }

    // origin === 'inferred'
    if (isNaN(accountStart) || nowMs - accountStart < NEW_USER_WAIT_MS) {
      return { send: false, reasonCode: 'new_user_waiting_period' };
    }
    const tz = validTimezone(user.timezone);
    const { day, hour } = localParts(nowDate, tz);
    if (inQuietHours(hour)) {
      return { send: false, reasonCode: 'quiet_hours' };
    }
    const cap = Number.isFinite(config?.dailyNudgeCap) ? Math.max(0, Math.floor(config.dailyNudgeCap)) : 1;
    const sentToday = state.nudges[day] || 0;
    if (sentToday >= cap) {
      return { send: false, reasonCode: 'daily_limit_reached' };
    }
    state.nudges = { [day]: sentToday + 1 };
    state.delivered[candId] = nowMs;
    await writeState(file, state);
    return { send: true, reasonCode: 'sent_suggestion' };
  });
}

import assert from 'node:assert/strict';
import { mkdtempSync } from 'node:fs';
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const botPath = process.argv[2];
const dir = mkdtempSync(path.join(os.tmpdir(), 'state-'));
process.env.STATE_DIR = dir;
const { decide, REASON_CODES } = await import(botPath);

const old = { id: 'u1', timezone: 'America/New_York', createdAt: '2026-01-01T00:00:00Z', profileCreatedAt: '2026-01-02T00:00:00Z' };
const fresh = { id: 'u2', timezone: 'UTC', createdAt: '2026-10-22T00:00:00Z', profileCreatedAt: '2026-10-22T01:00:00Z' };
const noon = new Date('2026-10-23T17:00:00Z'); // 13:00 New York
const night = new Date('2026-10-23T03:00:00Z'); // 23:00 New York
const cfg = { dailyNudgeCap: 2 };
const d = (user, id, origin, now = noon, config = cfg) => decide({ user, candidate: { id, origin }, now, config });

let r = await d(fresh, 'a', 'requested');
assert.equal(r.send, true);
r = await d(fresh, 'a', 'requested');
assert.deepEqual([r.send, r.reasonCode], [false, 'already_delivered']);
r = await d(fresh, 'b', 'inferred');
assert.deepEqual([r.send, r.reasonCode], [false, 'new_user_waiting_period']);
r = await d(fresh, 'r', 'reminder', night);
assert.equal(r.send, true);

r = await d(old, 'n0', 'inferred', night);
assert.deepEqual([r.send, r.reasonCode], [false, 'quiet_hours']);
assert.equal((await d(old, 'n1', 'inferred')).send, true);
assert.equal((await d(old, 'req', 'requested')).send, true); // requested does not use the cap
assert.equal((await d(old, 'n2', 'inferred')).send, true);
r = await d(old, 'n3', 'inferred');
assert.deepEqual([r.send, r.reasonCode], [false, 'daily_limit_reached']);
assert.equal((await d(old, 'n3', 'inferred', new Date(noon.getTime() + 86400000))).send, true); // next day
assert.equal((await d(old, 'req2', 'requested')).send, true);
assert.equal((await d(old, 'x', 'bogus')).reasonCode, 'unknown_notification_type');

// Concurrency: 8 processes, 5 inferred each, cap 3 -> exactly 3 sends.
const worker = `
import { decide } from ${JSON.stringify(botPath)};
const user = { id: 'conc', timezone: 'UTC', createdAt: '2026-01-01T00:00:00Z', profileCreatedAt: '2026-01-01T00:00:00Z' };
let sent = 0;
for (let i = 0; i < 5; i++) {
  const r = await decide({ user, candidate: { id: process.argv[2] + '-' + i, origin: 'inferred' }, now: new Date('2026-10-23T12:00:00Z'), config: { dailyNudgeCap: 3 } });
  if (r.send) sent++;
}
console.log(sent);`;
const runs = Array.from({ length: 8 }, (_, i) => new Promise((res) => {
  const p = spawn('node', ['--input-type=module', '-e', worker, String(i)], { env: process.env });
  let out = ''; p.stdout.on('data', (c) => (out += c)); p.stderr.on('data', (c) => process.stderr.write(c));
  p.on('close', () => res(Number(out.trim())));
}));
const total = (await Promise.all(runs)).reduce((a, b) => a + b, 0);
assert.equal(total, 3);

for (const c of REASON_CODES) assert.ok(!/error/i.test(c));
console.log('all checks passed');
